package crypto

import (
	"crypto/rand"
	"crypto/sha512"
	"errors"
	"math/big"
	"strings"
)

// Alphabet is the Crockford base32 alphabet (SPEC §2.1): no I, L, O, U.
const Alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

const (
	// ClaimLen is the number of symbols assigned by the server (routing, not secret).
	ClaimLen = 4
	// SecretLen is the number of symbols generated by the tray (40 bits, CSPRNG).
	SecretLen = 8
	// CodeLen is the full pairing code length: claim || secret.
	CodeLen = ClaimLen + SecretLen
)

// p256Order is n, the order of the P-256 base point.
var p256Order, _ = new(big.Int).SetString("FFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551", 16)

// ErrBadCode is returned for a pairing code that is not 12 Crockford symbols after normalization.
var ErrBadCode = errors.New("crypto: invalid pairing code")

// NormalizeCode applies the SPEC §2.1 input normalization: upper-case, strip '-' and spaces,
// map I→1, L→1, O→0. It does not validate the result (see ValidateCode).
func NormalizeCode(s string) string {
	s = strings.ToUpper(s)
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		switch r {
		case '-', ' ':
			continue
		case 'I', 'L':
			b.WriteByte('1')
		case 'O':
			b.WriteByte('0')
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// ValidateCode checks that a normalized code has exactly CodeLen symbols of the alphabet.
func ValidateCode(normalized string) error {
	if len(normalized) != CodeLen {
		return ErrBadCode
	}
	for i := 0; i < len(normalized); i++ {
		if strings.IndexByte(Alphabet, normalized[i]) < 0 {
			return ErrBadCode
		}
	}
	return nil
}

// FormatCode renders a normalized code in groups of 4 separated by '-' (CCCC-SSSS-SSSS).
func FormatCode(normalized string) string {
	var parts []string
	for i := 0; i < len(normalized); i += 4 {
		end := i + 4
		if end > len(normalized) {
			end = len(normalized)
		}
		parts = append(parts, normalized[i:end])
	}
	return strings.Join(parts, "-")
}

// GenerateSecret returns SecretLen uniformly random Crockford symbols from crypto/rand.
func GenerateSecret() (string, error) {
	var raw [SecretLen]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", err
	}
	out := make([]byte, SecretLen)
	for i, b := range raw {
		out[i] = Alphabet[int(b)&31] // 256 is a multiple of 32: no modulo bias
	}
	return string(out), nil
}

// CodeToW derives the SPAKE2 scalar w (SPEC §4.3): w = int_be(SHA-512(ASCII(code))) mod n,
// returned as 32 bytes big-endian. The input is normalized first.
func CodeToW(code string) ([]byte, error) {
	norm := NormalizeCode(code)
	if err := ValidateCode(norm); err != nil {
		return nil, err
	}
	sum := sha512.Sum512([]byte(norm))
	w := new(big.Int).SetBytes(sum[:])
	w.Mod(w, p256Order)
	out := make([]byte, 32)
	w.FillBytes(out)
	return out, nil
}
